with flagged as (select *, case when lag(event_time) over (partition by session_id order by event_time, id) is null or event_time > lag(event_time) over (partition by session_id order by event_time, id) + interval 30 days then 1 else 0 end as new_group_flag from web_events), sessions_web_events as (select *, sum(new_group_flag) over (partition by session_id order by event_time, id rows between unbounded preceding and current row) as session_no from flagged) select session_no, bit_and(duration_sec) as duration_sec_bit_and, max(session_no) filter (where event_type = 'page_view') as page_view_max_session_no, count(distinct event_type) as distinct_event_types from sessions_web_events group by session_no order by session_no;
